extern alias apiv5;
using System.Net;using System.Net.Http.Json;using System.Text;using System.Text.Json;using Microsoft.AspNetCore.Hosting;using Microsoft.AspNetCore.Mvc.Testing;using Microsoft.Extensions.DependencyInjection;using Npgsql;using SanSo.Api.Modules;using Xunit;using V5Program=apiv5::Program;
namespace SanSo.Api.V5.Tests;
public sealed class PostgresImportProjectionHttpV5Tests
{
 [Fact]public async Task LoginPreviewConfirmProjectsDurablyWithoutTaxGuess(){var cs=Environment.GetEnvironmentVariable("SANSO_RUNTIME_POSTGRES");if(string.IsNullOrWhiteSpace(cs))return;const string tenant="11111111-1111-1111-1111-111111111111";await using var factory=new WebApplicationFactory<V5Program>().WithWebHostBuilder(x=>{x.UseEnvironment("Development");x.UseSetting("ConnectionStrings:Postgres",cs);});using var client=factory.CreateClient();var identity=factory.Services.GetRequiredService<IdentityService>();var secret=IdentityService.GenerateTotpSecret();var email=$"v5-{Guid.NewGuid():N}@example.invalid";var user=identity.Register(email,"V5 Owner","Long-Safe-V5-Test-Password-2026!",secret);identity.AddMembership(tenant,user.Id,OrgRole.Owner);await InsertUser(cs,user.Id,email);var login=await client.PostAsJsonAsync("/api/auth/login",new{email,password="Long-Safe-V5-Test-Password-2026!",tenantId=tenant,totpCode=IdentityService.CurrentTotp(secret)});Assert.Equal(HttpStatusCode.OK,login.StatusCode);var token=(await login.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("token").GetString()!;var code=$"V5-{Guid.NewGuid():N}";using var form=new MultipartFormDataContent();var file=new ByteArrayContent(Encoding.UTF8.GetBytes($"order_code,amount,occurred_at\n{code},765000,2026-08-24T10:00:00+07:00"));file.Headers.ContentType=new("text/csv");form.Add(file,"file","orders.csv");using var previewRequest=new HttpRequestMessage(HttpMethod.Post,"/api/imports/preview"){Content=form};Auth(previewRequest,token,tenant);var preview=await client.SendAsync(previewRequest);Assert.Equal(HttpStatusCode.OK,preview.StatusCode);var p=await preview.Content.ReadFromJsonAsync<JsonElement>();Assert.True(p.GetProperty("persisted").GetBoolean());using var confirmRequest=new HttpRequestMessage(HttpMethod.Post,"/api/imports/confirm"){Content=JsonContent.Create(new{previewToken=p.GetProperty("previewToken").GetString(),checksum=p.GetProperty("checksum").GetString()})};Auth(confirmRequest,token,tenant);var confirm=await client.SendAsync(confirmRequest);if(confirm.StatusCode!=HttpStatusCode.OK)throw new Xunit.Sdk.XunitException($"Confirm {(int)confirm.StatusCode}: {await confirm.Content.ReadAsStringAsync()}");Assert.True((await confirm.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("persisted").GetBoolean());await AssertProjection(cs,tenant,code);}
 static void Auth(HttpRequestMessage r,string token,string tenant){r.Headers.Authorization=new("Bearer",token);r.Headers.Add("X-Tenant-Id",tenant);}static async Task InsertUser(string cs,string id,string email){await using var c=new NpgsqlConnection(cs);await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="INSERT INTO users(id,email,display_name,password_hash,mfa_enabled) VALUES($1::uuid,$2,'V5 test','managed',true)";q.Parameters.AddWithValue(id);q.Parameters.AddWithValue(email);await q.ExecuteNonQueryAsync();}static async Task AssertProjection(string cs,string tenant,string code){await using var c=new NpgsqlConnection(cs);await c.OpenAsync();await using var q=c.CreateCommand();q.CommandText="SELECT (SELECT count(*) FROM raw_events WHERE organization_id=$1::uuid AND payload->>'OrderCode'=$2),(SELECT count(*) FROM orders WHERE organization_id=$1::uuid AND code=$2),(SELECT count(*) FROM ledger_lines ll JOIN orders o ON o.id=ll.order_id WHERE o.code=$2 AND ll.amount=765000),(SELECT count(*) FROM tax_calculations tc JOIN ledger_lines ll ON ll.id=tc.ledger_line_id JOIN orders o ON o.id=ll.order_id WHERE o.code=$2 AND tc.status='NEEDS_REVIEW' AND tc.calculated_amount IS NULL AND tc.rule_version_id IS NULL)";q.Parameters.AddWithValue(tenant);q.Parameters.AddWithValue(code);await using var reader=await q.ExecuteReaderAsync();Assert.True(await reader.ReadAsync());for(var i=0;i<4;i++)Assert.Equal(1,reader.GetInt64(i));}
}
